const GAA_IMAGE_CACHE = new Map<string, string | null>()

export function clearGaaImageCache(): void {
  GAA_IMAGE_CACHE.clear()
}

/**
 * Resolves verified GAA luxury exercise image for any exercise name.
 * Uses exact lookup, cleaned naming, slug matching, alias dictionary, and keyword heuristics.
 * If not found, falls back to the official GAA brand logo seal if fallbackToBrand is true.
 */
export function resolveGaaExerciseImage(
  exerciseName: string | null | undefined,
  fallbackToBrand = true
): string | null {
  if (!exerciseName) {
    return fallbackToBrand ? BRAND_LOGO_FALLBACK_IMAGE : null
  }

  const cacheKey = `${exerciseName.trim().toLowerCase()}::${fallbackToBrand}`
  if (GAA_IMAGE_CACHE.has(cacheKey)) {
    return GAA_IMAGE_CACHE.get(cacheKey)!
  }

  const result = resolveGaaExerciseImageUncached(exerciseName, fallbackToBrand)
  GAA_IMAGE_CACHE.set(cacheKey, result)
  return result
}

function resolveGaaExerciseImageUncached(
  exerciseName: string,
  fallbackToBrand: boolean
): string | null {
  const rawLower = exerciseName.toLowerCase().trim()
  if (VERIFIED_GAA_EXERCISE_IMAGES[rawLower]) {
    return VERIFIED_GAA_EXERCISE_IMAGES[rawLower]
  }

  // Clean parentheticals, phase tags, superset codes: e.g. "Barbell Flat Bench Press (Strength 1A)"
  const cleaned = rawLower
    .replace(/^nasm\s*edge\s*[:\-]\s*/i, '')
    .replace(/^nasm\s*[:\-]\s*/i, '')
    .replace(/\s*\|\s*nasm(\s*edge)?$/i, '')
    .replace(/\s*-\s*nasm(\s*edge)?$/i, '')
    .replace(/\([^)]*\)/g, ' ')
    .replace(/\[[^\]]*\]/g, ' ')
    .replace(/phase\s*\d+/gi, ' ')
    .replace(/strength\s*\d+[a-z]?/gi, ' ')
    .replace(/stability\s*\d+[a-z]?/gi, ' ')
    .replace(/power\s*\d+[a-z]?/gi, ' ')
    .replace(/[-_&/]+/g, ' ')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()

  if (VERIFIED_GAA_EXERCISE_IMAGES[cleaned]) {
    return VERIFIED_GAA_EXERCISE_IMAGES[cleaned]
  }

  // Alias dictionary lookup
  if (EXERCISE_ALIAS_MAP[cleaned] && VERIFIED_GAA_EXERCISE_IMAGES[EXERCISE_ALIAS_MAP[cleaned]]) {
    return VERIFIED_GAA_EXERCISE_IMAGES[EXERCISE_ALIAS_MAP[cleaned]]
  }

  // Slug match
  const slug = cleaned.replace(/\s+/g, '-')
  for (const [key, path] of Object.entries(VERIFIED_GAA_EXERCISE_IMAGES)) {
    const keySlug = key.replace(/[^a-z0-9]+/g, '-')
    if (keySlug === slug) {
      return path
    }
  }

  // Substring matching
  for (const [key, path] of Object.entries(VERIFIED_GAA_EXERCISE_IMAGES)) {
    if (cleaned.length >= 4 && (key.includes(cleaned) || cleaned.includes(key))) {
      return path
    }
  }

  return fallbackToBrand ? BRAND_LOGO_FALLBACK_IMAGE : null
}

export const resolveNasmExerciseImage = resolveGaaExerciseImage
